#include <bits/stdc++.h>
using namespace std;
int n,m,ans=-1e9,b;
int a[21000000];
int main()
{
	freopen("and.in","r",stdin); 
	freopen("and.out","w",stdout);
	cin>>n>>m;
	for(int i=1;i<=n;i++)
	{
		cin>>a[i];
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=n;j>=0;j--)
		{
			b=a[j]&a[j-1];
			if(b>ans)
			{
				ans=b;
			}
		}
	}
	cout<<ans;
	return 0;
 } 
  
